from PIL import Image; import numpy as np
im=np.array(Image.open('observations/obs_0023.png').convert('RGB')).astype(int)
# classify gray box color vs floor vs wall
print('sample gray',im[330,180],'white box',im[400,470],'floor',im[450,300],'wall',im[250,350])
# find bottom-most gray pixel per column
def mask_close(c,tol=18):
    return (np.abs(im-np.array(c)).sum(axis=2)<tol)
g=mask_close(im[330,180]);w=mask_close(im[400,470])
for name,m in [('gray',g),('white',w)]:
    cols=np.where(m.any(axis=0))[0]
    print(name,'u range',cols.min(),cols.max())
    for u in range(cols.min(),cols.max()+1,10):
        r=np.where(m[:,u])[0]
        if len(r): print(' u',u,'vtop',r.min(),'vbot',r.max())
"

